-- A small slice of content/ for tests, captured when the service was seeded.
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('acorn', 'Acorn', 'Acorn was an application packaging and deployment framework for Kubernetes that let developers define an entire app — containers, volumes, secrets, and ingress — in a single file written in Acornfile, a CUE-derived configuration language. `acorn run` would then push that bundle to a cluster as an OCI image and reconcile it into the underlying Kubernetes primitives.

The project was built by the team behind Rancher and k3s (Darren Shepherd, Ibrahim Jarif, and others at Acorn Labs) as an attempt to hide Helm charts and raw YAML behind a simpler developer-facing abstraction. It shipped a CLI, a per-cluster controller, and a managed SaaS (Acorn Cloud) for sharing apps across clusters.

Acorn Labs pivoted away from the runtime in 2024 to focus on GPTScript and AI tooling, and the repository is no longer maintained. If you need the same shape of abstraction today, look at Score, KubeVela, Radius, or just Helm with a thin wrapper — all of which are actively developed. With the repository archived and no security updates planned, migration is the sensible path.', 'https://github.com/acorn-io/runtime', 'https://github.com/acorn-io/runtime#readme', 'https://github.com/acorn-io/runtime', 'Apache-2.0', 'abandoned', 'App Definition and Development', 'Application Definition & Image Build', NULL, NULL, NULL, NULL, NULL, '{"horizontal":true}', NULL, NULL, '{"status":"graveyard"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('aerakimesh', 'Aeraki Mesh', 'Aeraki Mesh ("Aeraki" is Greek for "breeze") is a management plane that extends Istio to handle non-HTTP Layer 7 protocols. Out of the box Istio and Envoy give rich traffic management for HTTP and gRPC, but protocols like Dubbo, Thrift, Redis, Kafka, and MetaProtocol need extra work — Aeraki provides that missing piece without forcing users to modify Istio or Envoy themselves.

Architecturally, Aeraki runs alongside istiod as a separate controller. It watches Istio''s service registry and pushes protocol-specific configuration to Envoy sidecars via EnvoyFilter resources. It ships MetaProtocol, a generic Layer 7 framework that lets operators add support for custom RPC protocols by writing a codec plugin instead of a full Envoy network filter in C++.

In practice Aeraki is most useful in environments with heavy Dubbo or Thrift traffic — typically larger Chinese tech stacks migrating from traditional microservice frameworks into Istio. For plain HTTP/gRPC workloads it adds no value over stock Istio. The project is a CNCF sandbox entry and is primarily maintained by Tetrate.', 'https://www.aeraki.net/', NULL, 'https://github.com/aeraki-mesh/aeraki', 'Apache-2.0', 'stable', 'Orchestration & Management', 'Service Mesh', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2022-06-17","devStatsUrl":"https://aerakimesh.devstats.cncf.io/","personas":["SREs","DevOps Engineers","Architects"],"tags":["Service Mesh"],"releaseRate":"Every few months","integrations":["Istio","Envoy"]}', '{"slack":"https://cloud-native.slack.com/messages/aeraki-mesh","blog":"https://www.aeraki.net/blog/"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('agentgateway', 'agentgateway', 'agentgateway is an AI-native proxy, written in Rust, for the traffic patterns that agentic systems create: agent-to-LLM, agent-to-tool, and agent-to-agent communication. It speaks the protocols of that world natively — Model Context Protocol (MCP) and Agent2Agent (A2A) — and layers security, observability, and governance on top, so platform teams can see and control what their agents are actually saying to models and tools.

Created by Solo.io and donated to the Linux Foundation, it slots into the existing cloud native stack rather than beside it: kgateway can act as its control plane, and at KubeCon + CloudNativeCon Europe 2026 the Istio project announced experimental agentgateway support alongside its Gateway API Inference Extension work. Capabilities include MCP multiplexing (federating many MCP servers behind one endpoint), tool-level RBAC, prompt guardrails, and OpenTelemetry-based tracing of agent conversations.

It occupies the emerging "agent gateway" niche alongside LiteLLM, Portkey, and the LLM-routing features appearing in traditional API gateways; its bet is that agent traffic deserves a purpose-built, vendor-neutral data plane rather than bolt-ons to HTTP gateways.', 'https://agentgateway.dev/', 'https://agentgateway.dev/docs/', 'https://github.com/agentgateway/agentgateway', 'Apache-2.0', 'beta', 'Orchestration & Management', 'API Gateway', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"status":"watch","trajectory":"rising"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('agentregistry', 'agentregistry', 'agentregistry is a cloud native registry for the building blocks of agentic AI systems: MCP servers, agents, and skills. It gives organizations a curated, single source of truth for which agents and tools are approved for use, and handles discovery and deployment of those artifacts across local development environments and Kubernetes clusters.

The project was created by Solo.io — its third agentic-infrastructure donation after kagent and agentgateway — and donated to the Linux Foundation, with a CNCF Sandbox application submitted in March 2026. It integrates with the projects you''d expect: Kubernetes for deployment, and Prometheus and OpenTelemetry for observability, with agentgateway as the natural enforcement point for what the registry curates.

The problem it addresses is real and growing: as teams accumulate dozens of MCP servers and agents of varying provenance, "which of these are vetted, versioned, and safe to run?" needs an answer that isn''t a wiki page. Whether the ecosystem standardizes on agentregistry or on registry features inside existing artifact stores (Artifact Hub, OCI registries) is the open question.', 'https://agentregistry.dev/', NULL, 'https://github.com/agentregistry-dev/agentregistry', 'Apache-2.0', 'alpha', 'Provisioning', 'Container Registry', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"status":"watch","trajectory":"rising"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('akri', 'Akri', 'Akri is a Kubernetes resource interface for exposing leaf devices — IP cameras, USB peripherals, OPC UA servers, Bluetooth sensors — as native cluster resources. It was originally built by Microsoft to solve a concrete edge/IoT problem: Kubernetes knows how to schedule pods onto nodes, but it has no native way to discover a thermal camera on the same LAN and hand it to a workload.

The project is written in Rust and works through two main components. Discovery Handlers run on each node and implement protocol-specific discovery (ONVIF, udev, OPC UA, and custom gRPC-based handlers). When a device is found, the Akri Controller creates an Instance CRD and exposes the device through the Kubernetes device plugin framework, so pods can request it with a standard resource limit. If the device appears on multiple nodes, Akri can schedule a broker pod per node to proxy access.

Akri sits in a niche next to projects like KubeEdge and k3s on the edge side, and is distinct from CSI or device plugins because it focuses on dynamic, network-attached leaf devices rather than local hardware. It has been a CNCF sandbox project since 2021, though development activity has slowed significantly in the last year.', 'https://docs.akri.sh', NULL, 'https://github.com/project-akri/akri', 'Apache-2.0', 'stable', 'Provisioning', 'Automation & Configuration', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2021-09-14","devStatsUrl":"https://akri.devstats.cncf.io/"}', '{"twitter":"https://twitter.com/ProjectAkri","slack":"https://kubernetes.slack.com/messages/C01D9L7QE8Z","blog":"https://medium.com/akri"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('antrea', 'Antrea', 'Antrea is a Kubernetes CNI plugin that uses Open vSwitch (OVS) as its dataplane to implement pod networking, NetworkPolicy, and service load balancing. It was created by VMware and is the CNI that underpins vSphere with Tanzu and several other VMware Kubernetes offerings.

Instead of relying on iptables or eBPF like Calico and Cilium do, Antrea programs OVS flow rules through a per-node agent written in Go. This gives it strong visibility tooling — `antctl traceflow` can inject a packet and show every OVS table hit it takes through the cluster — and makes it a natural fit for environments already running NSX or other OVS-based infrastructure. It supports overlay (Geneve, VXLAN, GRE) and no-encap modes, Windows nodes, multi-cluster networking via ClusterSet, and Kubernetes NetworkPolicy plus its own ClusterNetworkPolicy CRD with tiers and FQDN rules.

Antrea competes directly with Calico, Cilium, and Flannel. Its main draws are OVS-based debuggability, first-class Windows support, and tight integration with the VMware ecosystem; its main trade-off is that it lacks the kernel-level eBPF story that Cilium has made the default for new clusters. It has been a CNCF sandbox project since 2021.', 'https://antrea.io/', NULL, 'https://github.com/antrea-io/antrea', 'Apache-2.0', 'stable', 'Runtime', 'Cloud Native Network', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2021-04-28"}', '{"twitter":"https://twitter.com/projectantrea"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('apko', 'apko', 'apko is a tool from Chainguard that builds OCI container images declaratively from a YAML file and a set of APK packages. There is no Dockerfile, no `RUN` steps, and no container runtime involved in the build — apko resolves the package list, fetches the APKs, and writes a tarball that is already a valid OCI image.

Because the build is purely a package install with no arbitrary shell execution, apko produces bit-for-bit reproducible images: the same config and package versions give the exact same image hash on any machine. Every build also generates an SBOM in SPDX format and sets the image creation timestamp to the epoch (or a user-specified value) so layer digests are stable. It is the tool Chainguard uses to produce their Wolfi-based distroless images, and it is typically paired with `melange`, which builds the APKs themselves from source.

In the image build landscape apko sits alongside `ko` (for Go binaries), BuildKit (general Dockerfile builds), and Buildpacks. Its niche is supply-chain focused base images: minimal, reproducible, SBOM-attested, and free of the build tools and package managers that inflate attack surface in traditional Alpine or Debian images. If you are not using Wolfi or Alpine APK packages, apko is not the right tool.', 'https://apko.dev/', 'https://apko.dev/docs/', 'https://github.com/chainguard-dev/apko', 'Apache-2.0', 'stable', 'App Definition and Development', 'Application Definition & Image Build', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"status":"learn"}', '{"title":"apko: Build Minimal, Distroless OCI Images (Chainguard)","description":"apko builds minimal, distroless OCI images from apk packages. Reproducible, SBOM-attested, no shell. When to choose apko over a Dockerfile."}')
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('aquaproj', 'aquaproj', 'Aqua is a declarative CLI version manager. You list the tools you need — `terraform`, `kubectl`, `helm`, `gh`, hundreds more — with exact versions in an `aqua.yaml` file, and `aqua install` downloads them into a per-user cache and creates shim binaries on your `$PATH`. Run any tool and aqua transparently resolves it to the correct pinned version for the current directory.

Under the hood, aqua is a single Go binary that pulls from a community-maintained registry of package definitions (over 1,500 tools). Each registry entry describes where to download the binary for each OS/arch and, crucially, an SHA-256 checksum or Cosign signature. That makes aqua a practical supply-chain tool as well: every install can be checksum-verified, and you can enforce policies that refuse to install unsigned or unknown packages. It also generates lockfiles so CI and developer machines stay in sync.

In the broader ecosystem, aqua overlaps with `asdf`, `mise`, and Nix. Compared to asdf/mise it is narrower (binaries only, no language toolchains) but significantly faster and has better checksum handling out of the box. Compared to Nix it is drastically simpler at the cost of flexibility. It is a good fit for platform teams who want every engineer to run the same `kubectl` and `terraform` without writing bootstrap scripts.', 'https://aquaproj.github.io/', 'https://aquaproj.github.io/docs/', NULL, 'MIT', 'stable', 'Provisioning', 'Automation & Configuration', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', NULL, NULL, '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('argo', 'Argo', 'Argo is a family of four Kubernetes-native projects that share a common controller pattern but solve different problems. Argo CD is a GitOps continuous delivery controller that reconciles a Git repository of manifests against a cluster. Argo Workflows is a DAG/step-based workflow engine where each node is a Kubernetes Pod. Argo Events provides an event bus and sensors for triggering workflows or other actions from webhooks, Kafka, SQS, calendar events, and so on. Argo Rollouts extends Deployments with canary and blue-green strategies driven by Prometheus or other metrics.

All four are implemented as Kubernetes controllers in Go, using CRDs as their public API. Argo CD in particular has become the de-facto GitOps engine in the CNCF ecosystem: it renders manifests from Helm, Kustomize, Jsonnet, or raw YAML, computes a diff against live cluster state, and applies changes with pluggable sync waves and health checks. The web UI and `argocd` CLI make drift between Git and cluster state immediately obvious.

Argo graduated from the CNCF in December 2022 and is maintained by Intuit, Red Hat, Akuity, Codefresh, and others. Its main competitor in GitOps is Flux (also CNCF graduated); for workflows it overlaps with Tekton and Kubeflow Pipelines, though Argo Workflows is actually the engine Kubeflow Pipelines runs on top of.', 'https://argoproj.github.io/', NULL, 'https://github.com/argoproj/argo-cd', 'Apache-2.0', 'stable', 'App Definition and Development', 'Continuous Integration & Delivery', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"graduated","accepted":"2020-03-26","incubating":"2020-03-26","graduated":"2022-12-06","devStatsUrl":"https://argo.devstats.cncf.io/","personas":["Application Developers","ML Engineers","DevOps Engineers","Architects","Platform Engineers"],"tags":["application deployment","continuous deployment","data pipelines","machine learning","Kubernetes workflows"],"releaseRate":"7-14 days"}', '{"twitter":"https://twitter.com/argoproj","youtube":"https://www.youtube.com/channel/UCOvYmppcbOPm1viN6ust3lA","slack":"https://argoproj.github.io/community/join-slack","blog":"https://blog.argoproj.io/"}', '{"grouping":"platform","status":"adopt"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('armada', 'Armada', 'Armada is a multi-cluster batch job scheduler built for high-throughput, bursty workloads — the kind of problem that breaks the default Kubernetes scheduler. It was built at G-Research, a quantitative finance firm, to run millions of backtest and risk jobs per day across tens of thousands of nodes spread over multiple Kubernetes clusters.

The architecture separates a central Armada server (backed by Postgres and Pulsar for the event log) from per-cluster executor components. Jobs are submitted to Armada queues with fair-share priority; the server decides which cluster a job should run on, then the executor actually creates the Pod. Because queueing and scheduling happen outside any single Kubernetes scheduler, Armada can sustain job submission rates in the hundreds of thousands per hour, far beyond what `kube-scheduler` was designed for, and it handles cluster failover naturally.

Armada competes with Volcano, Kueue, and YuniKorn in the Kubernetes batch space, and more broadly with HTCondor and Slurm in traditional HPC. It is the right choice specifically when you have many small jobs, many clusters, and a need for fair-share queueing; for single-cluster ML training Kueue is usually simpler. It has been a CNCF sandbox project since 2022.', 'https://armadaproject.io/', NULL, 'https://github.com/armadaproject/armada', 'Apache-2.0', 'stable', 'Orchestration & Management', 'Scheduling & Orchestration', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2022-07-25","devStatsUrl":"https://armada.devstats.cncf.io/"}', '{"twitter":"https://twitter.com/oss_gr","slack":"http://slack.cncf.io/"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('artifacthub', 'Artifact Hub', 'Artifact Hub is a web-based discovery index for cloud-native packages — Helm charts, OLM operators, Falco rules, OPA policies, Tekton tasks, Krew kubectl plugins, Tinkerbell actions, KEDA scalers, Keptn integrations, Kyverno policies, and more. It solves the "where do I find a chart for X" problem that existed after the original `helm/charts` monorepo was deprecated in 2020 and chart publishing became federated.

It''s a Go backend with a React frontend, backed by PostgreSQL. Repositories self-register (`helm repo add` style) and Artifact Hub periodically crawls them to ingest metadata, README files, values schemas, signatures, and security scan results from Trivy. Packages are ranked by signals like maintainer verification, Cosign signatures, OpenSSF Scorecard results, and recency. You can search across every indexed artifact type in one place and, for charts specifically, get inline values documentation and install commands.

Artifact Hub is maintained by the CNCF itself (it moved from a Helm subproject to a top-level CNCF project in 2020, now incubating) and the public instance at artifacthub.io is the closest thing the ecosystem has to a central package registry. You can also self-host it if you need to index private repositories alongside public ones.', 'https://artifacthub.io', NULL, 'https://github.com/artifacthub/hub', 'Apache-2.0', 'stable', 'App Definition and Development', 'Application Definition & Image Build', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"incubating","accepted":"2020-06-25","incubating":"2024-05-30","devStatsUrl":"https://artifacthub.devstats.cncf.io/"}', '{"twitter":"https://twitter.com/cncfartifacthub"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('athenz', 'Athenz', 'Athenz is a service-to-service authentication and fine-grained authorization system built at Yahoo (now part of Verizon Media / Yahoo again) and open sourced in 2016. It issues short-lived X.509 certificates and JWT-like access tokens that workloads use to prove their identity to each other, and it evaluates RBAC policies to decide what those identities are allowed to do.

The core architecture is two services: ZMS (the authorization management system) holds the source-of-truth for domains, roles, and policies in a central database; ZTS (the token service) runs regionally and mints service certificates and access tokens against that policy, doing the hot-path work without hitting ZMS on every request. Workloads authenticate to ZTS with a bootstrapped identity — typically a node attestation provided by AWS, GCP, or a Kubernetes service account — and receive an SVID-style cert they can then present to peers or to an Envoy sidecar.

In the broader identity landscape Athenz overlaps significantly with SPIFFE/SPIRE, HashiCorp Vault''s PKI engine, and cert-manager. Its distinguishing feature is that it ties identity issuance directly to a centralized RBAC policy model, which is why it''s still used heavily inside large operators like Yahoo, LinkedIn, and Verizon Media. Outside of those environments most new projects reach for SPIFFE first.', 'https://www.athenz.io', NULL, 'https://github.com/AthenZ/athenz', 'Apache-2.0', 'stable', 'Provisioning', 'Key Management', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2021-01-26","devStatsUrl":"https://athenz.devstats.cncf.io/"}', '{"twitter":"https://twitter.com/athenzio","slack":"https://athenz.slack.com/"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('atlantis', 'Atlantis', 'Atlantis is a self-hosted Terraform pull request automation server. You point it at your GitHub, GitLab, Bitbucket, or Azure DevOps repo, and when someone opens a PR touching Terraform code Atlantis runs `terraform plan` and posts the output as a PR comment. Reviewers approve the plan by commenting `atlantis apply`, at which point Atlantis runs the apply and reports back. The Terraform state is locked on the PR while it''s open so two PRs can''t race each other.

It''s a single Go binary that you run somewhere with network access to your VCS webhook endpoint and credentials for your cloud provider. Workflows are configurable per-repo via an `atlantis.yaml` — you can define projects, pin Terraform versions (via the tfenv-like `terraform_version` field), run custom pre/post hooks, and scope applies to specific directories. It supports Terragrunt, OpenTofu, and policy checks via Conftest.

Atlantis was originally built at HootSuite in 2017, open sourced in 2018, and became a CNCF sandbox project in 2024. It competes with Terraform Cloud/HCP, Spacelift, env0, and Scalr — the main appeal being that it''s free, self-hosted, and you keep your state and credentials entirely inside your own infrastructure. For teams that just want PR-driven Terraform without a SaaS dependency, it''s the obvious choice.', 'https://www.runatlantis.io/', NULL, 'https://github.com/runatlantis/atlantis', 'Apache-2.0', 'stable', 'Provisioning', 'Automation & Configuration', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2024-06-18"}', NULL, '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('aws-lambda', 'AWS Lambda', 'AWS Lambda is Amazon''s flagship serverless compute service and the function-as-a-service offering that effectively defined the category when it launched in 2014. You upload a function, declare its memory and timeout, and Lambda runs it on demand in a managed execution environment, scaling from zero to thousands of concurrent invocations without you provisioning servers, patching operating systems, or sizing fleets. Billing is per-millisecond of execution against the memory you request, so idle code costs nothing.

The execution model is event-driven. Functions are invoked by events from across the AWS ecosystem (S3 object writes, DynamoDB streams, SQS and Kinesis messages, EventBridge rules, IoT topics, Cognito triggers, and many others) or synchronously through API Gateway, Application Load Balancer, or a Lambda Function URL. Managed runtimes are provided for Node.js, Python, Java, .NET, and Ruby, with the `provided.al2023` custom runtime covering Go, Rust, C++, and anything else that can produce a Linux binary. Both x86_64 and ARM64 (Graviton) architectures are supported, and functions can be packaged either as zip archives or as OCI container images up to 10 GB pulled from Amazon ECR, which is the usual route when dependencies are large, such as machine learning models or scientific libraries.

Cold starts are the headline operational concern: the first invocation into a fresh environment pays for container setup and runtime initialisation, typically tens to hundreds of milliseconds for Node.js or Python and longer for the JVM or .NET, though SnapStart materially reduces that for Java, .NET, and Python by restoring a pre-initialised snapshot. Provisioned Concurrency keeps warm environments on standby for latency-sensitive paths at additional cost. Teams reach for Lambda when they want event glue between AWS services, lightweight HTTP APIs fronted by API Gateway or a Function URL, scheduled jobs via EventBridge, or background processing of queues and streams, particularly where traffic is spiky and scale-to-zero economics matter more than the steady-state efficiency of a long-running container.', 'https://aws.amazon.com/lambda/', 'https://docs.aws.amazon.com/lambda/', NULL, 'Commercial', 'stable', 'Serverless', 'Tools', NULL, NULL, NULL, NULL, NULL, '{"icon":true}', NULL, NULL, NULL, NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('backstage', 'Backstage', 'Backstage is an open-source framework for building internal developer portals, originally created at Spotify in 2016 and donated to the CNCF in 2020. At its core it is a TypeScript/React application with a Node.js backend, plus a plugin system that lets you bolt on integrations with the rest of your stack: Kubernetes, GitHub, Jenkins, ArgoCD, PagerDuty, Grafana, Jira, and several hundred others.

The centerpiece is the Software Catalog — a YAML-driven (`catalog-info.yaml` in each repo) registry of components, APIs, systems, resources, and the teams that own them, stored in Postgres and visualized as a graph. On top of that sit two other pillars: Software Templates (a scaffolder that generates new repos/services from golden-path templates using Cookiecutter-style actions) and TechDocs (a docs-as-code system that renders Markdown from each repo into a searchable site using MkDocs). Plugins live inside the monorepo you scaffold from `@backstage/create-app` — Backstage is explicitly not a SaaS; you fork it, add plugins, and run your own instance.

Backstage is effectively the de-facto platform for IDPs in the cloud-native world, and Spotify, Red Hat (Janus/RHDH), Roadie, and others sell managed or opinionated distributions on top of it. The main criticism is fair: it''s a React monorepo you have to own and upgrade, and the learning curve for writing plugins is steep. Alternatives like Port, Cortex, and OpsLevel trade that ownership for a SaaS model.', 'https://backstage.io/', NULL, 'https://github.com/backstage/backstage', 'Apache-2.0', 'stable', 'App Definition and Development', 'Application Definition & Image Build', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"incubating","accepted":"2020-09-08","incubating":"2022-03-15","devStatsUrl":"https://backstage.devstats.cncf.io/","personas":["Developers","SREs"],"tags":["Developer Portals","IDP","Service Catalog","Observability"],"releaseRate":"Backstage releases versions on a monthly cadence, with a weekly next release of the main branch.","integrations":["Kubernetes","GitHub","GitLab","Bitbucket","Azure DevOps","Jenkins","and more with plugins"]}', '{"discord":"https://discord.gg/backstage-687207715902193673","blog":"https://backstage.io/blog"}', '{"status":"watch"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('bank-vaults', 'Bank-Vaults', 'Bank-Vaults is a set of tools and a Kubernetes operator that make HashiCorp Vault easier to run on Kubernetes. Operating Vault correctly — auto-unsealing, storing the root keys safely, configuring auth methods and policies in a reproducible way, and getting secrets to applications — is surprisingly fiddly, and Bank-Vaults packages a set of opinions that handle most of it for you.

The project is built around three main pieces. The Vault Operator deploys and manages Vault clusters from a CRD, including auto-initialization and auto-unseal using KMS keys from AWS, GCP, Azure, or plain Kubernetes Secrets. A mutating webhook injects secrets directly into Pods as environment variables or files by rewriting them at admission time — so application code can use `vault:secret/data/mysecret#key` references in its env vars and get the real value at runtime, without needing a Vault-aware SDK or a sidecar. A Go library wraps the Vault API and adds higher-level helpers that the other components share.

Bank-Vaults was originally built by Banzai Cloud and is now maintained as the `bank-vaults` GitHub org; it joined the CNCF sandbox in 2024. It overlaps with Vault''s own official Helm chart and the Vault Secrets Operator from HashiCorp, and with External Secrets Operator for the secret-injection story. Its niche is teams that want a batteries-included, CRD-driven way to run Vault on Kubernetes without writing their own operator.', 'https://bank-vaults.dev/', NULL, 'https://github.com/bank-vaults/bank-vaults', 'Apache-2.0', 'stable', 'Provisioning', 'Security & Compliance', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2024-06-18","devStatsUrl":"https://bankvaults.devstats.cncf.io/"}', NULL, '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('bfe', 'BFE', 'BFE (Beyond Front End) is a Layer 7 reverse proxy and load balancer written in Go, originally developed at Baidu where it handles the bulk of the company''s front-door traffic — reportedly over a trillion requests per day. It was open sourced in 2019 and donated to the CNCF as a sandbox project in 2020.

Architecturally BFE sits in the same category as Nginx, HAProxy, and Envoy: terminate TLS, parse HTTP/HTTPS/HTTP/2/HTTP/3 requests, run them through a rules engine, and forward to a backend cluster. Its distinguishing features are a condition-expression-based routing language (`req_host_in("example.com") && req_path_prefix_in("/api")`) instead of Nginx-style location blocks, and a modular pluggable filter chain that lets you add request/response processing in Go without forking the proxy. It supports multi-tenancy with per-tenant config, health checks, connection pooling, dynamic config reload, and active/passive backend probing.

In practice BFE is an interesting alternative if you want an Nginx-class edge proxy written in Go that you can extend in Go, but outside of Baidu and a few other large Chinese deployments adoption is limited. For most teams, Envoy (plus a control plane like Istio or Contour) or Nginx remain the default choices.', 'https://www.bfe-networks.net', NULL, 'https://github.com/bfenetworks/bfe', 'Apache-2.0', 'stable', 'Orchestration & Management', 'Service Proxy', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2020-06-25","devStatsUrl":"https://bfe.devstats.cncf.io/"}', '{"twitter":"https://twitter.com/BfeNetworks"}', '{"status":"skip"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('bootc', 'bootc', 'bootc ("bootable containers") lets you ship and update an entire Linux operating system as an OCI container image. You build a `FROM quay.io/fedora/fedora-bootc:41` image, add your own packages and config with normal Dockerfile instructions, push it to a registry, and `bootc switch` on the target host pulls and boots it as the root filesystem. Upgrades become `bootc upgrade`, and rollbacks are just the previous image.

Under the hood bootc is built on top of OSTree (the same content-addressed filesystem technology behind Fedora Silverblue and Red Hat CoreOS) but presents a container-native interface instead of the older `rpm-ostree` workflow. The host runs a transactional, image-based filesystem where the OS is immutable between reboots; `/etc` and `/var` are writable but the rest of the tree is swapped atomically on update. Because the artifact is a standard OCI image, you build, sign, scan, and distribute it with the same tooling as your application containers — Cosign, Trivy, any registry.

bootc is maintained in the `bootc-dev` GitHub org, primarily driven by Red Hat, and became a CNCF sandbox project in 2025. It''s the foundation for Fedora/CentOS/RHEL bootc image modes and a direct conceptual cousin of Flatcar, Talos, and Chainguard''s container-optimized OSes.', 'https://bootc.dev/', 'https://bootc.dev/bootc/', 'https://github.com/bootc-dev/bootc', 'Apache-2.0 OR MIT', 'stable', 'Runtime', 'Container Runtime', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"sandbox","accepted":"2025-01-21","devStatsUrl":"https://bootc.devstats.cncf.io"}', NULL, '{"status":"watch"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('influxdb', 'InfluxDB', 'InfluxDB is a time-series database purpose-built for metrics, events, and other timestamped data. Data is written using the InfluxDB line protocol — a simple text format of `measurement,tag=value field=value timestamp` — typically via Telegraf, the project''s companion collection agent that ships with hundreds of input plugins.

InfluxDB 1.x used a custom TSM storage engine and the InfluxQL query language. 2.x added Flux, a functional data-scripting language, plus a tasks/alerting UI. InfluxDB 3 is a complete rewrite in Rust on top of Apache Arrow, DataFusion, and Parquet: data is held in-memory in Arrow format, persisted as Parquet files to object storage, and queried with SQL via DataFusion (with InfluxQL still supported). The Core edition is open source under MIT/Apache-2.0 dual license; clustering, replication, and long-term historical query live in the commercial Enterprise and Cloud editions.

In the observability stack it is typically paired with Grafana for dashboards and Telegraf or an OpenTelemetry collector for ingestion. Compared to Prometheus it is a true pushed-ingest database with much higher cardinality tolerance in 3.x, and compared to TimescaleDB it is not a Postgres extension — you get a dedicated engine but give up the rest of the Postgres ecosystem.', 'https://www.influxdata.com/', 'https://docs.influxdata.com/', 'https://github.com/influxdata/influxdb', 'Apache-2.0 OR MIT', 'stable', 'CNAI', 'Workload Observability', NULL, NULL, NULL, NULL, NULL, '{"icon":true}', NULL, NULL, '{"status":"explore"}', NULL)
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('kubernetes', 'Kubernetes', 'Kubernetes is a container orchestrator with a declarative API. You describe the desired state of your workloads as objects — Pods, Deployments, StatefulSets, Services, Ingresses, ConfigMaps, Secrets, Jobs, CronJobs — and a set of controllers continuously reconciles the cluster toward that state. This controller pattern is the single idea the entire project is built around: every feature, from core workload types to third-party operators, is implemented as a reconciliation loop watching an object in the API.

A cluster has a control plane and a set of nodes. The control plane runs the API server (the only component that talks to storage), etcd (the backing key-value store holding every object), the scheduler (which assigns Pods to nodes based on resource requests, affinities, taints, and topology constraints), and the controller manager (which runs the built-in reconciliation loops for ReplicaSets, endpoints, nodes, service accounts, and so on). Each node runs the kubelet, which takes Pod specs from the API server and drives a container runtime over CRI to actually start containers, and kube-proxy (or eBPF equivalents like Cilium) to implement ClusterIP Services via iptables/IPVS/eBPF. Networking, storage, and container runtime are all pluggable via CNI, CSI, and CRI, which is how the ecosystem ended up with dozens of interchangeable network and storage backends.

Multi-tenancy is handled through namespaces, RBAC, ResourceQuotas, NetworkPolicies, and PodSecurity admission. Extension is handled through CustomResourceDefinitions plus controllers — "the operator pattern" — which is why Kubernetes has become the substrate for things as diverse as databases, CI systems, ML platforms, and service meshes.

It came out of Google''s Borg lineage, was the first project to graduate from the CNCF, and is now the de facto API for running server-side workloads in essentially every cloud and most data centers. Its main competition at this point is itself: the interesting choices are between distributions (EKS, GKE, AKS, OpenShift, k3s, Talos, kubeadm) rather than between Kubernetes and something else.', 'https://kubernetes.io/', 'https://kubernetes.io/docs/home/', 'https://github.com/kubernetes/kubernetes', 'Apache-2.0', 'stable', 'Orchestration & Management', 'Scheduling & Orchestration', NULL, NULL, NULL, NULL, NULL, '{"icon":true,"horizontal":true,"stacked":true}', '{"status":"graduated","accepted":"2016-03-10","incubating":"2016-03-10","graduated":"2018-03-06","devStatsUrl":"https://k8s.devstats.cncf.io/"}', '{"twitter":"https://twitter.com/kubernetesio","youtube":"https://www.youtube.com/channel/UCZ2bu0qutTOM0tHYa_jkIwg","slack":"http://slack.k8s.io/","blog":"http://blog.kubernetes.io/","mailingList":"https://groups.google.com/forum/#!forum/kubernetes-dev"}', '{"grouping":"plumbing","status":"advocate","confidence":"deep-experience","trajectory":"rising","firstUsed":"2017-03","lastUsed":"Present","makesMeFeel":"🚀","why":"Everyone should adopt Kubernetes, otherwise you''re missing out on the collective knowledge and tooling of the cloud-native ecosystem.","spicyTake":"You can even run Java on it now, so there''s really no excuse not to."}', '{"title":"Kubernetes Tutorials, Guides, and Best Practices","description":"Learn Kubernetes with practical tutorials, production patterns, and troubleshooting guides for platform engineers and developers."}')
--> statement-breakpoint
INSERT INTO `technologies` (`id`, `name`, `description`, `website`, `documentation`, `source`, `license`, `status`, `category`, `subcategory`, `aliases`, `related_technologies`, `use_cases`, `features`, `learning_resources`, `logos`, `cncf`, `community`, `matrix`, `seo`) VALUES ('rust', 'Rust', 'Rust is a statically typed, compiled systems programming language that provides memory and thread safety without a garbage collector. It was started at Mozilla by Graydon Hoare in 2006, reached 1.0 in 2015, and is now governed by the Rust Foundation with an open RFC and edition process.

The defining feature is the ownership and borrow-checker model: every value has a single owner, references are checked at compile time to prevent dangling pointers and data races, and lifetimes encode how long a borrow is valid. The result is C/C++-level runtime performance with the memory-safety guarantees usually associated with managed languages. Rust compiles to native code via LLVM, supports no_std bare-metal targets, and has first-class WebAssembly support through `wasm32-unknown-unknown` and `wasm32-wasip1` targets, making it the default choice for writing WASI components and browser-side Wasm modules. The toolchain — `rustup`, `cargo`, `rustc`, `clippy`, and `rustfmt` — is shipped as a unified stack, and dependencies are managed through crates.io.

Cloud-native projects written in Rust include the Linkerd2-proxy data plane, Firecracker microVMs, Deno and Bun runtimes, the TiKV distributed KV store, the Databend and Polars analytics engines, InfluxDB 3.0, the Wasmtime and WasmEdge runtimes, and significant parts of the Linux kernel. Rust is dual-licensed under MIT or Apache-2.0.', 'https://www.rust-lang.org/', 'https://doc.rust-lang.org/stable/book/', 'https://github.com/rust-lang/rust', 'MIT OR Apache-2.0', 'stable', 'Wasm', 'Languages', NULL, NULL, NULL, NULL, NULL, '{"icon":true}', NULL, NULL, '{"status":"learn"}', NULL)
